insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (111, 'Searching for Cicadas', 'Gibbes, Lesley', NULL, 'This lovely story about a child and their grandfather searching for cicadas is part of the award-winning narrative nonfiction Nature Storybooks series. In the summertime, Grandpa and I go cicada-watching. We put our camping gear into my wagon and walk down to the local reserve. Last year we saw five Green Grocers, three Yellow Mondays and one Floury Baker. Can we find the rare Black Prince this year? This picture book brings together award winners Lesley Gibbes and Judy Watson to showcase the wonder and beauty of cicadas as well as highlight the common summer pastime of cicada-watching.', 'verified', '111_searching_for_cicadas.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (112, 'The Little Yellow Digger', 'Gilderdale, Betty', NULL, 'When the little yellow digger comes along to the zoo to dig a bigger hippo pool, it gets into all sorts of trouble.', 'verified', '112_the_little_yellow_digger.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (113, 'Banjo and Ruby Red', 'Gleeson, Libby', NULL, 'Banjo is an old farm dog and Ruby Red is a haughty chicken, and they never see eye to eye. Can they ever be friends?', 'verified', '113_banjo_and_ruby_red.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (114, 'Boy Overboard', 'Gleitzman, Morris', NULL, 'Jamal and Bibi have a dream: To lead Australia to football glory in the next World Cup. But first they must face pirates, storms, and assassins. Can Jamal and his family survive their incredible journey and get to Australia?', 'verified', '114_boy_overboard.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (115, 'Go Go and the Silver Shoes', 'Godwin, Jane', NULL, 'Go Go is confident and creative about her clothes, even though most of them are hand-me-downs from her three older brothers. The only new things she ever gets are underwear and shoes. That''s why she loves new shoes, especially her latest and most precious silver shoes. But despite her mother''s warnings, Go Go wears them on a family picnic and loses one in the creek. Go Go is devastated, but continues to wear her one remaining silver shoe, until one day a new girl at school realises that she has one just like it... A beautiful story about being confidently individual and about the power of friendship.', 'verified', '115_go_go_and_the_silver_shoes.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (116, 'The BEST Hiding Place', 'Godwin, Jane', NULL, '"Archie has found the best hiding place. But after a while, it feels too quiet. Is the game still on? Has Archie been forgotten?"--Publisher''s description.', 'verified', '116_the_best_hiding_place.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (117, 'Today we have NO PLANS', 'Godwin, Jane', NULL, 'A busy week, a slower day Brings time to dream and time to play. From the creators of the much-loved All Through the Year comes a journey through a week in the life of an Australian family, celebrating those precious days that have no plans.', 'verified', '117_today_we_have_no_plans.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (118, 'Tilly', 'Godwin, Jane & Walker, Anna', NULL, 'Tillys found the perfect hiding place to keep her special treasures. No one knows about it, not even her big brothers and sister, who know everything. But one day, something happens that Tilly could never have imagined... Jane Godwin and Anna Walker have created a wistful, enchanting and timeless story about an old house, a young girl, and how the small things we hold dear stay with us always.', 'verified', '118_tilly.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (119, 'Swoop', 'Godwin, Nicole', NULL, 'Magpie has one job, one desire, one purpose: KEEP THE EGGS SAFE. Always on alert for danger, will Magpie''s determination be enough when rock-carrying intruders arrive? Why do magpies swoop and why do we have such a fascination with them? Discover more about these clever, cheeky and charming songbirds through this delightful book. Reading level varies from child to child, but we recommend this book for ages 5 to 9.', 'verified', '119_swoop.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (120, 'Wendy', 'Gordon, Gus', NULL, '"Wendy doesn''t want to be just any old chicken. She wants ADVENTURE. She wants EXCITEMENT. She wants TO BE A STAR! And then a travelling circus comes to town..."--Back cover.', 'verified', '120_wendy.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (121, 'The Energy Bus for Kids', 'Gordon, Jon', NULL, 'More than 100,000 sold An illustrated adaptation of the bestselling business fable, The Energy Bus, teaches children the benefits of staying positive In this illustrated adaptation of the bestselling fable, The Energy Bus, author Jon Gordon shows children how to overcome negativity, bullies and everyday challenges to be their best. The Energy Bus For Kids is a story that will teach kids how to find their inner motivation and pass on that positive energy to others. The Energy Bus For Kids presents five rules for the "Ride of Your Life" Teaches kids how to fuel your ride with positive energy Shares with kids how to love the people you share your journey with and how to enjoy the ride Positive kids become positive adults. So get kids on the Energy Bus and infuse their lives with a newfound vision, attitude, and positivity.', 'verified', '121_the_energy_bus_for_kids.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (122, 'Xavier in the Meantime', 'Gordon, Kate', NULL, 'Sometimes Xavier wakes up feeling hopeless. Every new doctor this will fix it. Removing him from school this will fix it. The therapy group this will fix it. And his dad moving out. Maybe, this will fix it. His daily affirmations seem to be helping, yet the black dog never really goes away. But Xavier has a plan. Enlisting the help of best friend Aster, he tries to convince his dad to turn the family hogget farm into a therapy retreat for the group session kids. But he is up against decades of tradition, his parents who are on a break, and the spectre of the black dog. Can Xavier learn to cherish the moments in between the struggles - the moments in the meantime?', 'verified', '122_xavier_in_the_meantime.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (123, 'The Concrete Garden', 'Graham, Bob', NULL, 'After a cold, dark winter, doors opened. Children spilled out like sweets from a box. Amanda was last one out of the tower block. She brought some chalk with her. On every inch of the concrete outside, the children drew pictures of everything they could think of, from flowers and snails, to spaceships and queens. Before long, a beautiful and exotic garden spread out across the concrete. From master storyteller Bob Graham comes a charming, and gently post-pandemic story about finding optimism after a dark spell, and the nurturing power of community friendships in an urban setting.', 'verified', '123_the_concrete_garden.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (124, 'Ellie''s Dragon', 'Graham, Bob', NULL, 'From master storyteller Bob Graham comes an adorable and affecting tale about imaginary friends and the bittersweet nature of growing up. When Ellie is very small, she finds a lovable newborn dragon on a carton of eggs in the grocery store. Ellie calls him Scratch, takes him home, and moves him into her dollhouse. Her mother can’t see Scratch, and her teacher doesn’t notice when Ellie brings Scratch to preschool, yet her friends are amazed. Ellie is lucky to have an affectionate, house-trained dragon like Scratch! But dragons get quite large as they grow. And Ellie is growing, too, moving from dollhouses to dance parties, not noticing that Scratch’s brilliant green scales are beginning to fade a little. . . . Beloved picture-book creator Bob Graham illustrates the joys of imagination and friendship in this touching story. With his signature gentle wit and warm, whimsically detailed illustrations, he captures the bond between girl and dragon, as well as the changes that come with time’s passage. A wistful, quietly thought-provoking tribute to the friends who appear when we need them most, even if it’s just for a little while.', 'verified', '124_ellies_dragon.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (125, 'Jigsaw - A Puzzle in the Post', 'Graham, Bob', NULL, 'Serendipity and positive thinking come into play as a family searches for a missing puzzle piece in Bob Graham''s enchanting story with a sweet surprise ending.', 'verified', '125_jigsaw_a_puzzle_in_the_post.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (126, 'Rose Meets Mr Wintergarten', 'Graham, Bob', NULL, 'All the children in the Summers household are afraid of Mr Wintergarten. His garden is grey and sunless, and it is guarded, they say, by a dog like a wolf and a saltwater crocodile. By contrast, the garden of his sunny new neighbours, the Summers, is a playground of happiness and flowers. One day, Rose''s ball goes over the fence into Mr Wintergarten''s garden and, prompted by her mother, Rose visits her frosty next-door neighbour, bearing hot fairy cakes and flowers. "A little kindness goes a long way" is the subtle moral depicted in this gentle tale by award-winning Australian author-illustrator Bob Graham.', 'verified', '126_rose_meets_mr_wintergarten.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (127, 'Let''s Get a Pup!', 'Graham, Bob', NULL, 'When Kate and her parents visit the animal shelter, an adorable puppy charms them, but it is very hard to leave an older dog behind.', 'verified', '127_lets_get_a_pup.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (128, 'Grandad''s Magic', 'Graham, Bob', NULL, 'Alison''s grandfather performs magic tricks every Sunday when the family gathers for dinner.', 'verified', '128_grandads_magic.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (129, 'Go Away, Worry Monster!', 'Graham, Brooke', NULL, 'Worry Monster loves "helping" Archie worry, especially the night before he starts his new school. Archie feels so anxious that his head hurts, his tummy flutters and his heart pounds. He soon realizes the only way to feel better is to make Worry Monster go away. He does his belly breaths and faces facts to challenge his inner fears. Children have the potential to engage and empathise with Archie and Worry Monster both through the text and the subtle gestures and fleeting emotions captured in the beautiful illustrations. Encouraging children to name their anxiety is an evidence-based, current strategy used by psychologists to assist children in separating themselves from their anxiety. Go Away, Worry Monster! gives children this and other useful strategies to cope, showing them how to make their own Worry Monsters leave during stressful periods of their lives, from starting or changing schools, to a change in family dynamics. Created by an author and illustrator passionate about helping children to cope with common emotional difficulties, this is an invaluable, life-changing resource for young children and their parents in guiding emotional development.', 'verified', '129_go_away_worry_monster.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (130, 'The Island', 'Greder, Armin', NULL, 'In the morning the people of the island found a man sitting on the shore, there where fate and the ocean currents had set him and his frail raft in the night. When he saw them coming towards him, he rose to his feet. He was not like them. This internationally acclaimed, award-winning picture book is astonishing, powerful and timely.', 'verified', '130_the_island.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (131, 'The Detective''s Guide to Ocean Travel', 'Greenberg, Nicki', NULL, 'The first middle-grade novel from award-winning author Nicki Greenberg, this book is a classic whodunnit mystery set aboard a grand ocean liner in the 1920s. With first-class glitz and glamour and a deliciously plotted intrigue featuring an uppity stage star, a missing diamond, a leopard and a loveable cast of child sleuths, The Detective''s Guide to Ocean Travel is an exciting romp on the high seas perfect for fans of Murder Most Unladylike and The Good Thieves.', 'verified', '131_the_detectives_guide_to_ocean_travel.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (132, 'Our Country - Where History Happened', 'Greenwood, Mark', NULL, 'The second title in the OUR COUNTRY series, celebrating and contextualising the richness of Australia''s history, and where it happened. In every corner of Australia, history happened. The pages of this book are a journey through tens of thousands of years. Our history is recorded in ancient rock art, in the flag flown at the Eureka Stockade, by Burke and Wills'' tree. All around our coastline history unfolded in shipwrecks and ship arrivals. Sometimes tragic, often regrettable, always formative, history is commemorated from Tasmania and throughout the mainland at the sites of prisons and massacres. From the birthplace of a new federated nation at the beginning of the twentieth century in Sydney''s Centennial Park to Eddie Mabo''s struggle for acknowledgement of land rights in the 1990s, history happened all around Our Country.', 'verified', '132_our_country_where_history_happened.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (133, 'The Second Sky', 'Guest, Patrick', NULL, 'The first thing Gilbert sees when he hatches from his egg is the sky. It is love at first sight and from that moment on Gilbert longs to fly like other birds. But Penguins don''t fly, they waddle, and so begins Gilbert''s quest to find his place in the world. Great things happen when you reach for the sky.', 'verified', '133_the_second_sky.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (134, 'August & Jones', 'Harry, Pip', NULL, 'Eleven-year-old Jones Kirby has just moved to Sydney from her farm in country New South Wales. She''s missing her alpacas and wide-open paddocks and can''t get used to her family''s tiny city apartment. She''s also worried that her vision is blurry - she lost her eye to cancer as a toddler. Could it be another tumour? Enrolling at her new school, Jones meets shy, awkward August Genting. He loves fun facts, the library and knitting as much as Jones loves rock climbing and being outdoors. Who would have thought they''d become fast friends? At home, August''s parents are fighting. And for Jones, the news from the doctor is not good. To cheer themselves up, the pair hatch a brilliant plan: the August and Jones Must-See Bucket List. Together, this brave duo will set out to meet a rare monkey, run across the Harbour Bridge and even climb Australia''s highest mountain. After all, with your best friend beside you, anything is possible! ''A delightfully Australian book and a sensitive picture of what family and friendship means ... Highly recommended'' ReadPlus ''I wish I was reading it for the first time again - that is how much I loved it ... Pip Harry balances the reality of illness and the joys and travails of being a child with a deft hand. She never overplays the emotional drama of illness and family rifts, but offsets them with the power of friendship, love and strength of character. Harry really portrays the vicissitudes of life with big-hearted sensitivity'' Readings ''August & Jones is a big-hearted story for middle readers from an award-winning author, about how friendship can lend us courage to defy adversity'' Sydney Morning Herald Praise for Pip Harry: ''Fresh, authentic, poignant, light and dark by turns - I wish I''d read this when I was growing up.'' JANE GODWIN ''Pip Harry''s words are imbued with hope and the message that falling down doesn''t mean you never get back up.'' Children''s Books Daily ''Pip Harry is a masterful storyteller ... funny and relatable.'' Readings ''Fresh, funny and very contemporary ... reminds us that we all have the chance to change the course of our life and make a difference in the world.'' Better Reading', 'verified', '134_august_jones.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (135, 'Strangers on Country', 'Hartley, David', NULL, 'This book is fiction and non-fiction. The fictional part (or factional) tells the story of 5 white castaways or runaways who were found and cared for by Indigenous groups. There are 5 pairs of stories: each pair of stories has one written by an Indigenous author and one by a non-Indigenous author. After each story there is a non-fiction section that tells the true story from history.', 'verified', '135_strangers_on_country.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (136, 'Blue Flower', 'Hartnett, Sonya', NULL, 'Not all cats are tabby. Not all trees are tall. Not all clouds are white... and not all flowers are yellow. A beautiful and inspiring story, from award-winning writer Sonya Hartnett, about the discovery that being different can be something wonderful.', 'verified', '136_blue_flower.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (137, 'No! Never! A Cautionary Tale', 'Hathorn, Libby & Hathorn-Jarman, Lisa', NULL, 'There was a child, the sweetest ever, until she learned these words: ''NO! NEVER!'' Georgie is a sweet little girl who always makes her parents happy... until she discovers one powerful phrase: No! Never! It suddenly becomes her answer to every request, from tidying up her toys to going to bed. Her parents are at their wits'' end, but what happens when they decide to try saying No! Never! themselves? A lovely, lively look at the Terrible Twos (or Threes, or Fours, or Fives...) from mother-daughter team Libby Hathorn and Lisa Hathorn-Jarman, with debut illustrator Mel Pearce. Perfect for any parent dealing with tantrums, defiant behaviour or communication issues.', 'verified', '137_no_never_a_cautionary_tale.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (138, 'Huda and Me', 'Hayek, H', NULL, 'Huda''s sitting in the airport lounge, fiddling with our tickets. I can tell she''s excited because she has a little smile on her face and she keeps glancing at her pink digital watch. I can''t believe we''re doing this. I can''t believe we''re running away from home. Well, we''re not really running away. We''ll come back. We''re running to our parents. On the other side of the world. When their parents have to travel to Beirut unexpectedly, twelve-year-old Akeal and his six siblings are horrified to be left behind in Melbourne with the dreaded Aunt Amel as their babysitter. Things do not go well, and Akeal''s naughty little sister, Huda, hatches a bold plan to escape. After stealing Aunt Amel''s credit card to buy plane tickets to Lebanon, Huda persuades her reluctant favourite brother, Akeal, to come with her. So begins their hair-raising and action-packed journey to reunite with their parents half a world away, in a city they''ve grown up dreaming about but have never seen. A fresh and funny story of sibling love, adventure and courage, Huda and Me is one of a kind.', 'verified', '138_huda_and_me.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (139, 'Chrysanthemum', 'Henkes, Kevin', NULL, 'Chrysanthemum loves her name, until she starts going to school and the other children make fun of it.', 'verified', '139_chrysanthemum.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (140, 'Kitten''s First Full Moon', 'Henkes, Kevin', NULL, 'When Kitten mistakes the full moon for a bowl of milk, she ends up tired, wet, and hungry trying to reach it.', 'verified', '140_kittens_first_full_moon.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (141, 'Wemberly Worried', 'Henkes, Kevin', NULL, 'Wemberly worried about everything.Big things. Little things. And things in between. Then it was time for school to start.And Wemberly worried even more.If you ever worry (or know someone who does), this is the book for you', 'verified', '141_wemberley_worried.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (142, 'Chester''s Way', 'Henkes, Kevin', NULL, '“I like croquet and peanut butter and making my bed.” There is only one way for Chester to do things—his own way. “You definitely have a mind of your own,” said Chester’s mother. “That’s one way to put it,” said Chester’s father. Luckily Chester’s best friend, Wilson, likes doing things just the same way as Chester. When they cut their sandwiches, it''s always diagonally. When they ride their bikes, they always use hand signals. If Chester is hungry, Wilson is too. They''re two of a kind—until indomitable Lilly, who has her own way of doing things, moves into the neighborhood. Because Lilly has her own way of doing things! Written and illustrated by Kevin Henkes, the nationally bestselling and celebrated creator of Lilly''s Purple Plastic Purse, Kitten''s First Full Moon, and Chrysanthemum, Chester''s Way is a classic picture book about friendship for kids ages 3-7. With sweet good humor and charming pictures, the book''s themes of making new friends, accepting others, and trying new things resonate when curled up with a parent or at story time.', 'verified', '142_chesters_way.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (143, 'Sheila Rae, the Brave', 'Henkes, Kevin', NULL, '"I am very brave," Sheila Rae said, patting herself on the back. She wasn''t afraid of anything - not thunder, not lightning, not the big black dog at the end of the block. And when she wanted to walk home a new way and Louise wouldn''t, she called her sister a scaredy-cat and set out alone. But all the bravado in the world failed to help when Sheila Rae found herself lost. Luckily, her sister was not far behind ... A warm and loving story of sibling sympathy and support.', 'verified', '143_sheila_rae_the_brave.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (144, 'Hey, Little Ant', 'Hoose, Hannah & Phillip', NULL, 'A song in which an ant pleads with the kid who is tempted to squish it.', 'verified', '144_hey_little_ant.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (145, 'When I Was Five', 'Howard, Arthur', NULL, 'A six year old boy describes the things he liked when he was five, and compares them to the things he likes now. 4 yrs+', 'verified', '145_when_i_was_five.jpg');
